From a4470b9d101a4e4a54c1051b075980567ee1fdd6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:02:20 +0100
Subject: [PATCH] KPluginMetaData: read bundled third-party components from
 metadata

Plugins had no way to list the libraries they bundle, so their licenses
could not be shown anywhere. A new Components key is now read into a list
of KAboutComponent, with the license from an identifier or a file.

BUG: 520379
---
 src/lib/plugin/kpluginmetadata.cpp | 26 ++++++++++++++++++++++++++
 src/lib/plugin/kpluginmetadata.h   | 23 +++++++++++++++++++++++
 2 files changed, 49 insertions(+)

diff --git a/src/lib/plugin/kpluginmetadata.cpp b/src/lib/plugin/kpluginmetadata.cpp
index 765828cc..39658a27 100644
--- a/src/lib/plugin/kpluginmetadata.cpp
+++ b/src/lib/plugin/kpluginmetadata.cpp
@@ -362,6 +362,32 @@ QList<KAboutPerson> KPluginMetaData::otherContributors() const
     return aboutPersonFromJSON(d->m_rootObj[QLatin1String("OtherContributors")]);
 }

+QList<KAboutComponent> KPluginMetaData::components() const
+{
+    QList<KAboutComponent> ret;
+    const QJsonArray components = d->m_rootObj[QLatin1String("Components")].toArray();
+    for (const QJsonValue &val : components) {
+        const QJsonObject obj = val.toObject();
+        const QString name = KJsonUtils::readTranslatedString(obj, QStringLiteral("Name"));
+        if (name.isEmpty()) {
+            qCWarning(KCOREADDONS_DEBUG) << "Invalid plugin metadata: Attempting to create a KAboutComponent from JSON without 'Name' property:" << obj;
+            continue;
+        }
+        const QString description = KJsonUtils::readTranslatedString(obj, QStringLiteral("Description"));
+        const QString version = obj[QLatin1String("Version")].toString();
+        const QString website = obj[QLatin1String("Website")].toString();
+        const QString licenseFile = obj[QLatin1String("LicenseFile")].toString();
+        if (!licenseFile.isEmpty()) {
+            const QString path = QFileInfo(d->m_fileName).absoluteDir().absoluteFilePath(licenseFile);
+            ret.append(KAboutComponent(name, description, version, website, path));
+        } else {
+            const KAboutLicense::LicenseKey key = KAboutLicense::byKeyword(obj[QLatin1String("License")].toString()).key();
+            ret.append(KAboutComponent(name, description, version, website, key == KAboutLicense::Custom ? KAboutLicense::Unknown : key));
+        }
+    }
+    return ret;
+}
+
 QString KPluginMetaData::category() const
 {
     return d->m_rootObj[QLatin1String("Category")].toString();
diff --git a/src/lib/plugin/kpluginmetadata.h b/src/lib/plugin/kpluginmetadata.h
index e2bfd187..27f8005a 100644
--- a/src/lib/plugin/kpluginmetadata.h
+++ b/src/lib/plugin/kpluginmetadata.h
@@ -23,6 +23,7 @@
 class QPluginLoader;
 struct QStaticPlugin;
 class KPluginMetaDataPrivate;
+class KAboutComponent;
 class KAboutPerson;
 /*!
   \class KPluginMetaData
@@ -108,11 +109,20 @@ class KAboutPerson;
         \li OtherContributors
         \li otherContributors()
         \li object array (KAboutPerson)
+    \row
+        \li Components
+        \li components()
+        \li object array (KAboutComponent)
    \endtable

   The Authors, Translators and OtherContributors keys are expected to be
   list of objects that match the structure expected by KAboutPerson::fromJSON.

+  The Components key lists third-party components bundled with the plugin, as
+  objects with the keys Name, Description, Version, Website and either License
+  (a license identifier known to KAboutLicense::byKeyword()) or LicenseFile (a
+  path to the license text, relative to the directory of the metadata file).
+
   An example metadata json file could look like this:
   \badcode
   {
@@ -182,6 +192,12 @@ class KCOREADDONS_EXPORT KPluginMetaData
      */
     Q_PROPERTY(QList<KAboutPerson> otherContributors READ otherContributors CONSTANT)

+    /*!
+     * \property KPluginMetaData::components
+     * \since 6.33
+     */
+    Q_PROPERTY(QList<KAboutComponent> components READ components CONSTANT)
+
     /*!
      * \property KPluginMetaData::category
      */
@@ -404,6 +420,13 @@ public:
      */
     QList<KAboutPerson> otherContributors() const;

+    /*!
+     * Returns the third-party components bundled with this plugin.
+     *
+     * \since 6.33
+     */
+    QList<KAboutComponent> components() const;
+
     /*!
      * Returns the categories of this plugin (e.g. "playlist/skin").
      */
